SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#1d2b4f");
  SZGame2D.enableClassicControls("always");
  let acesa = false;
  let lenha1 = false;
  let lenha2 = false;
  const placa = SZGame2D.createSprite({ x: 296, y: 200, w: 48, h: 48, image: "apagada" });
  const luz = SZGame2D.createSprite({ x: 296, y: 200, w: 48, h: 48, image: "acesa" });
  // Quando acontecer
  SZGame2D.onKey("ArrowLeft", () => {
    lenha1 = true;
  }, "pedido-jade_events_0");
  SZGame2D.onKey("ArrowRight", () => {
    lenha2 = true;
  }, "pedido-jade_events_1");
  SZGame2D.onKey("Space", () => {

  }, "pedido-jade_events_2");
  SZGame2D.onKey("Enter", () => {

  }, "pedido-jade_events_3");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawLabel(ctx, "A fogueira dos ninhos", 20, 35, "#fff3ce", 18, "left");
    SZGame2D.drawLabel(ctx, "Setas pegam lenha. Espaço acende.", 20, 68, "#fff3ce", 18, "left");
    if (acesa) {
      SZGame2D.drawSprite(ctx, luz);
      SZGame2D.drawLabel(ctx, "A fogueira da Jade acendeu.", 20, 120, "#fff3ce", 18, "left");
    } else {
      SZGame2D.drawSprite(ctx, placa);
    }
  }, "pedido-jade_loops_0");
}, "__sz-project");

SZGame2D.onStart(function __szProjectRun() {
  const __szProjectRunContext = window.__SZProjectLifecycle.begin(() => SZGame2D.restart());
  // Ao iniciar
  SZGame2D.setupStage(640, 480, "#1d2b4f");
  SZGame2D.enableClassicControls("always");
  let acesa = false;
  let lenha1 = false;
  let lenha2 = false;
  const placa = SZGame2D.createSprite({ x: 296, y: 200, w: 48, h: 48, image: "apagada" });
  const luz = SZGame2D.createSprite({ x: 296, y: 200, w: 48, h: 48, image: "acesa" });
  // Quando acontecer
  SZGame2D.onKey("ArrowLeft", () => {
    lenha1 = true;
  }, "pedido-jade_events_0");
  SZGame2D.onKey("ArrowRight", () => {
    lenha2 = true;
  }, "pedido-jade_events_1");
  SZGame2D.onKey("Space", () => {
    if (lenha1) {
      if (lenha2) {
        acesa = true;
      }
    }
  }, "pedido-jade_events_2");
  SZGame2D.onKey("Enter", () => {
    acesa = false;
    lenha1 = false;
    lenha2 = false;
  }, "pedido-jade_events_3");
  // Enquanto estiver rodando
  // O jogo roda 60 passos por segundo: cada volta desenha um "quadro" do filme.
  SZGame2D.gameLoop(function update() {
    SZGame2D.clear();
    SZGame2D.drawLabel(ctx, "A fogueira dos ninhos", 20, 35, "#fff3ce", 18, "left");
    SZGame2D.drawLabel(ctx, "Setas pegam lenha. Espaço acende.", 20, 68, "#fff3ce", 18, "left");
    if (acesa) {
      SZGame2D.drawSprite(ctx, luz);
      SZGame2D.drawLabel(ctx, "A fogueira da Jade acendeu.", 20, 120, "#fff3ce", 18, "left");
    } else {
      SZGame2D.drawSprite(ctx, placa);
    }
  }, "pedido-jade_loops_0");
}, "__sz-project");
